    @Override
    @Transactional
    public synchronized void addScene(Scene scene) throws ServiceException {
        LOGGER.info("addScene start, sceneName:{}, sceneType: {}", scene.getSceneName(), scene.getSceneType());
        String timeStamp = DateTime.now().toString(DateTimeFormat.forPattern("yyyyMMddHHmmss"));
        int lockRes = scenesMgrDBMapper.tryLockSceneTask(SCENE_CREATE_LOCK, timeStamp);
        LOGGER.info("addScene lockRes:{}", lockRes);
        if (lockRes != NO_SCENE_CREATING_FLAG) {
            throw new VisibleException(ErrorCode.ERROR,
                LocaleUtil.getMessage("prs.web.experienceAssurance.scene.task.multiInstance.limit"));
        }
        try {
            changeCityCode(scene);
            checkScenesNumberLimit();
            checkScene(scene);
            checkSceneNameExists(scene.getSceneName());
            checkSceneExists(scene.getSceneType(), scene.getCityCode(), scene.getSceneCode());
            SceneTypeEnum sceneTypeEnum = SceneTypeEnum.toEnum(scene.getSceneType());
            List<CellInfo> cells = querySceneCells(scene, sceneTypeEnum);
            checkSceneCellsSize(cells.size(), sceneTypeEnum);
            createNewScene(scene, cells);
            writeCreateOrEditOperationLog(scene.getSceneName(), Constants.OPERATION_LEVEL_SUCCESS, true);
            LOGGER.info("addScene success.");
        } catch (Exception e) {
            LOGGER.info("addScene error.", e);
            writeCreateOrEditOperationLog(scene.getSceneName(), Constants.OPERATION_LEVEL_FAILED, true);
            throw e;
        } finally {
            scenesMgrDBMapper.tryUnlockSceneTask(SCENE_CREATE_LOCK, timeStamp);
        }
    }
